<template><Transition name="ui-bulk"><div v-if="selectedCount>0" class="ui-bulk" role="status"><div><UiCheckbox :model-value="allSelected" :indeterminate="indeterminate" :aria-label="selectionLabel" @update:model-value="emit('toggleAll',$event)"/><strong>{{ selectionLabel || `已选择 ${selectedCount} 项` }}</strong></div><div class="ui-bulk__actions"><slot/><UiButton density="dense" variant="quiet" @click="emit('clear')">{{ clearLabel }}</UiButton></div></div></Transition></template>
<script setup lang="ts">import UiButton from './UiButton.vue';import UiCheckbox from './UiCheckbox.vue';withDefaults(defineProps<{selectedCount:number;allSelected?:boolean;indeterminate?:boolean;selectionLabel?:string;clearLabel?:string}>(),{allSelected:false,indeterminate:false,selectionLabel:'',clearLabel:'取消选择'});const emit=defineEmits<{clear:[];toggleAll:[boolean]}>();</script>
<style scoped>.ui-bulk{display:flex;min-height:42px;align-items:center;justify-content:space-between;gap:12px;padding:6px 10px;border:1px solid var(--ui-border);border-radius:var(--ui-radius);background:var(--ui-surface-strong);font-size:12px}.ui-bulk>div,.ui-bulk__actions{display:flex;align-items:center;gap:8px}.ui-bulk-enter-active,.ui-bulk-leave-active{transition:opacity var(--ui-motion-fast),transform var(--ui-motion-fast)}.ui-bulk-enter-from,.ui-bulk-leave-to{opacity:0;transform:translateY(-4px)}@media(max-width:540px){.ui-bulk{align-items:flex-start;flex-direction:column}.ui-bulk__actions{width:100%;overflow:auto}}</style>
